import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M3 5h10a1 1 0 0 1 0 2H3a1 1 0 1 1 0-2m0 4h10a1 1 0 0 1 0 2H3a1 1 0 0 1 0-2"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M4 7h12a1 1 0 0 1 0 2H4a1 1 0 1 1 0-2m0 4h12a1 1 0 0 1 0 2H4a1 1 0 0 1 0-2"] as readonly string[];

export const EqualsIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="equals" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
EqualsIcon.displayName = `Blueprint6.Icon.EqualsIcon`;

/**
 * @deprecated Use {@link EqualsIcon} instead.
 */
export const Equals: typeof EqualsIcon = EqualsIcon;

export default EqualsIcon;
