import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M12 0a1 1 0 0 0-1 1v2H9a1 1 0 0 0 0 2h2v2a1 1 0 1 0 2 0V5h2a1 1 0 1 0 0-2h-2V1a1 1 0 0 0-1-1M0 4a1 1 0 0 1 1-1h3.5a1 1 0 0 1 0 2H2v2a1 1 0 0 1-2 0zm1 12a1 1 0 0 1-1-1v-3a1 1 0 1 1 2 0v2h2.5a1 1 0 1 1 0 2zm11 0a1 1 0 0 0 1-1v-3a1 1 0 1 0-2 0v2H9a1 1 0 1 0 0 2zm-5.5-4a2.5 2.5 0 1 0 0-5 2.5 2.5 0 0 0 0 5"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M15 0a1 1 0 0 1 1 1v3h3a1 1 0 1 1 0 2h-3v3a1 1 0 1 1-2 0V6h-3a1 1 0 1 1 0-2h3V1a1 1 0 0 1 1-1M1 4a1 1 0 0 0-1 1v4a1 1 0 0 0 2 0V6h3a1 1 0 0 0 0-2zM0 19a1 1 0 0 0 1 1h4a1 1 0 1 0 0-2H2v-3a1 1 0 1 0-2 0zm15 1h-4a1 1 0 1 1 0-2h3v-3a1 1 0 1 1 2 0v4a1 1 0 0 1-1 1m-7-5a3 3 0 1 0 0-6 3 3 0 0 0 0 6"] as readonly string[];

export const AddClipIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="add-clip" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
AddClipIcon.displayName = `Blueprint6.Icon.AddClipIcon`;

/**
 * @deprecated Use {@link AddClipIcon} instead.
 */
export const AddClip: typeof AddClipIcon = AddClipIcon;

export default AddClipIcon;
