import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["m16 1.99-16 6 16 6-4-6z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["m20 3.02-20 7 20 7-5-7z"] as readonly string[];

export const DirectionLeftIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="direction-left" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
DirectionLeftIcon.displayName = `Blueprint6.Icon.DirectionLeftIcon`;

/**
 * @deprecated Use {@link DirectionLeftIcon} instead.
 */
export const DirectionLeft: typeof DirectionLeftIcon = DirectionLeftIcon;

export default DirectionLeftIcon;
