import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["m-.01 6.66 7.34 2 2 7.33 6.66-16z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["m0 8.33 9.17 2.5 2.5 9.17L20 0z"] as readonly string[];

export const GeolocationIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="geolocation" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
GeolocationIcon.displayName = `Blueprint6.Icon.GeolocationIcon`;

/**
 * @deprecated Use {@link GeolocationIcon} instead.
 */
export const Geolocation: typeof GeolocationIcon = GeolocationIcon;

export default GeolocationIcon;
