import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M16 13H3l6-9h1l2 2h1zm-2.5-3.5-1-2.5h-1l-2-2-3 4.5L9 8l1 1 1-1zM5.94 7l-4.122 6H0l5-6z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M20 16H4l7-11h1l2 2h1zm-4-5-1.5-3h-1l-1-1-1-1L8 11.5l3-1.5 1 1 1-1zM8.055 8 2.79 16H0l7-8z"] as readonly string[];

export const MountainIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="mountain" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
MountainIcon.displayName = `Blueprint6.Icon.MountainIcon`;

/**
 * @deprecated Use {@link MountainIcon} instead.
 */
export const Mountain: typeof MountainIcon = MountainIcon;

export default MountainIcon;
