import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M12 6H4a2 2 0 1 0 0 4h8a2 2 0 1 0 0-4M4 4h8a4 4 0 0 1 0 8H4a4 4 0 0 1 0-8"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M15 7H5a3 3 0 1 0 0 6h10a3 3 0 0 0 0-6M5 5h10a5 5 0 1 1 0 10H5A5 5 0 0 1 5 5"] as readonly string[];

export const StadiumGeometryIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="stadium-geometry" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
StadiumGeometryIcon.displayName = `Blueprint6.Icon.StadiumGeometryIcon`;

/**
 * @deprecated Use {@link StadiumGeometryIcon} instead.
 */
export const StadiumGeometry: typeof StadiumGeometryIcon = StadiumGeometryIcon;

export default StadiumGeometryIcon;
