import * as React from "react";
import type { SVGIconProps } from "../../../svgIconProps";
import { SvgIconContainerNext } from "../../svgIconContainerNext";

const PATHS = [] as readonly string[];

export const BlankIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    return (
        <SvgIconContainerNext iconName="blank" ref={ref} {...props}>
            {PATHS.map((d, i) => (
                <path key={i} d={d} />
            ))}
        </SvgIconContainerNext>
    );
});
BlankIcon.displayName = "Blueprint6.Icon.Next.BlankIcon";
export default BlankIcon;
