import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M11 15a1 1 0 1 0 2 0v-2h2a1 1 0 1 0 0-2H5V1a1 1 0 0 0-2 0v2H1a1 1 0 1 0 0 2h2v7a1 1 0 0 0 1 1h7zm1-12H6v2h5v5h2V4a1 1 0 0 0-1-1"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M14 19a1 1 0 1 0 2 0v-3h3a1 1 0 1 0 0-2H6V1a1 1 0 1 0-2 0v3H1a1 1 0 1 0 0 2h3v9a1 1 0 0 0 1 1h9zm1-15H8v2h6v6h2V5a1 1 0 0 0-1-1"] as readonly string[];

export const CropIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="crop" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
CropIcon.displayName = `Blueprint6.Icon.CropIcon`;

/**
 * @deprecated Use {@link CropIcon} instead.
 */
export const Crop: typeof CropIcon = CropIcon;

export default CropIcon;
