import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M0 14h2V2H0zm6 0h1V2H6zm2 0h1V2H8zm-5 0h2V2H3zM15 2v12h1V2zm-5 12h1V2h-1zm2 0h2V2h-2z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M6 16.98h2v-14H6zm3 0h1v-14H9zm-6 0h2v-14H3zm-3 0h2v-14H0zm16 0h2v-14h-2zm-4 0h1v-14h-1zm7-14v14h1v-14zm-5 14h1v-14h-1z"] as readonly string[];

export const BarcodeIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="barcode" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
BarcodeIcon.displayName = `Blueprint6.Icon.BarcodeIcon`;

/**
 * @deprecated Use {@link BarcodeIcon} instead.
 */
export const Barcode: typeof BarcodeIcon = BarcodeIcon;

export default BarcodeIcon;
