import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M9 14v2H7v-2zm1-14L9 12H7L6 0z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M12 16v4H8v-4zm1-16-1 14H8L7 0z"] as readonly string[];

export const HighPriorityIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="high-priority" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
HighPriorityIcon.displayName = `Blueprint6.Icon.HighPriorityIcon`;

/**
 * @deprecated Use {@link HighPriorityIcon} instead.
 */
export const HighPriority: typeof HighPriorityIcon = HighPriorityIcon;

export default HighPriorityIcon;
