import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M5 15c0 .55.45 1 1 1h4c.55 0 1-.45 1-1v-1H5zm7-15H4c-.55 0-1 .45-1 1v1h10V1c0-.55-.45-1-1-1M5 7v6h6V7l2-4H3zm2 0c0-.55.45-1 1-1s1 .45 1 1v2c0 .55-.45 1-1 1s-1-.45-1-1z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M6.97 19c0 .55.45 1 1 1h4c.55 0 1-.45 1-1v-2h-6zm-3-15 3 4v8h6V8l3-4zm5 5c0-.55.45-1 1-1s1 .45 1 1v2c0 .55-.45 1-1 1s-1-.45-1-1zm6-9h-10c-.55 0-1 .45-1 1v2h12V1c0-.55-.45-1-1-1"] as readonly string[];

export const TorchIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="torch" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
TorchIcon.displayName = `Blueprint6.Icon.TorchIcon`;

/**
 * @deprecated Use {@link TorchIcon} instead.
 */
export const Torch: typeof TorchIcon = TorchIcon;

export default TorchIcon;
