import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M15 1H1c-.6 0-1 .5-1 1v12c0 .6.4 1 1 1h14c.6 0 1-.4 1-1V2c0-.5-.4-1-1-1M6 13H2v-2h4zm0-3H2V8h4zm0-3H2V5h4zm8 6H7v-2h7zm0-3H7V8h7zm0-3H7V5h7z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M19 1H1c-.6 0-1 .5-1 1v16c0 .5.4 1 1 1h18c.5 0 1-.5 1-1V2c0-.5-.5-1-1-1M7 17H2v-3h5zm0-4H2v-3h5zm0-4H2V6h5zm11 8H8v-3h10zm0-4H8v-3h10zm0-4H8V6h10z"] as readonly string[];

export const ThIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="th" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
ThIcon.displayName = `Blueprint6.Icon.ThIcon`;

/**
 * @deprecated Use {@link ThIcon} instead.
 */
export const Th: typeof ThIcon = ThIcon;

export default ThIcon;
