import * as React from "react";
import type { SVGIconProps } from "../../svgIconProps";
import { IconSize } from "../../iconTypes";
import { SVGIconContainer } from "../../svgIconContainer";

/** Path data for the 16px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_16 = ["M7 11a1 1 0 0 0-1-1H4.8a.8.8 0 0 1-.706-1.176L8.588.397A.75.75 0 0 1 10 .75V5a1 1 0 0 0 1 1h1.2a.8.8 0 0 1 .706 1.176l-4.494 8.427A.75.75 0 0 1 7 15.25z"] as readonly string[];

/** Path data for the 20px grid; matches {@link generate-icon-paths.mjs} / `<Icon />` from core. */
const PATHS_20 = ["M8 13a1 1 0 0 0-1-1H4.942a.942.942 0 0 1-.81-1.422L10.11.49A1.02 1.02 0 0 1 11 0a1 1 0 0 1 1 1v6a1 1 0 0 0 1 1h2.058a.942.942 0 0 1 .81 1.422L9.89 19.51A1.02 1.02 0 0 1 9 20a1 1 0 0 1-1-1z"] as readonly string[];

export const GenerateIcon: React.FC<SVGIconProps> = React.forwardRef<any, SVGIconProps>((props, ref) => {
    const isLarge = (props.size ?? IconSize.STANDARD) >= IconSize.LARGE;
    const paths = isLarge ? PATHS_20 : PATHS_16;
    return (
        <SVGIconContainer iconName="generate" ref={ref} {...props}>
            {paths.map((d, i) => (
                <path key={i} d={d} fillRule="evenodd" />
            ))}
        </SVGIconContainer>
    );
});
GenerateIcon.displayName = `Blueprint6.Icon.GenerateIcon`;

/**
 * @deprecated Use {@link GenerateIcon} instead.
 */
export const Generate: typeof GenerateIcon = GenerateIcon;

export default GenerateIcon;
